from taf.fdsw.rc.interfaces.FDSW20B.fdsw import FDSW20B
from taf.fdsw.rc.interfaces.FDSW21A.autoconnection import AutoConfiguration21A


class FDSW21A(FDSW20B):
    VERSION_NAME = 'FDSW21A'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW21A, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)

        self.autoconnection = AutoConfiguration21A(client=self._client)
